import { MeshBasicNodeMaterial } from 'three/webgpu';
import { color, mix, smoothstep, texture, uv } from 'three/tsl';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry } = ctx.THREE;
  const root = new Group();
  const ownedMaterials = [];
  const ownedGeometries = [];
  const timelines = [];
  let disposed = false;

  const colors = config.intent?.visualSpec?.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10'
  };

  const cardWidth = 3.2;
  const cardHeight = 2.0;

  const backdropGeometry = new PlaneGeometry(cardWidth, cardHeight);
  const backdropMaterial = new MeshBasicNodeMaterial({
    transparent: false,
    depthWrite: true
  });

  backdropMaterial.colorNode = mix(
    color(colors.surface),
    color(colors.ink),
    smoothstep(0.0, 1.0, uv().y)
  );

  const backdrop = new Mesh(backdropGeometry, backdropMaterial);
  backdrop.position.z = -0.04;
  root.add(backdrop);
  ownedGeometries.push(backdropGeometry);
  ownedMaterials.push(backdropMaterial);

  const grainGeometry = new PlaneGeometry(cardWidth * 0.98, cardHeight * 0.98);
  const grainMaterial = new MeshBasicNodeMaterial({
    color: colors.ink,
    transparent: true,
    opacity: 0.16,
    depthWrite: false
  });

  const grain = new Mesh(grainGeometry, grainMaterial);
  grain.position.z = -0.01;
  root.add(grain);
  ownedGeometries.push(grainGeometry);
  ownedMaterials.push(grainMaterial);

  const accentGeometry = new PlaneGeometry(0.06, 0.72);
  const accentMaterial = new MeshBasicNodeMaterial({
    color: colors.accent
  });
  const accent = new Mesh(accentGeometry, accentMaterial);
  accent.position.set(-1.22, -0.02, 0.045);
  root.add(accent);
  ownedGeometries.push(accentGeometry);
  ownedMaterials.push(accentMaterial);

  const imageGeometry = new PlaneGeometry(1.28, 1.28);
  const imageMaterial = new MeshBasicNodeMaterial({
    color: colors.paper,
    transparent: true,
    opacity: 0.82,
    depthWrite: false
  });
  const imagePlane = new Mesh(imageGeometry, imageMaterial);
  imagePlane.position.set(0.78, 0.02, 0.035);
  root.add(imagePlane);
  ownedGeometries.push(imageGeometry);
  ownedMaterials.push(imageMaterial);

  const imageUrl = config.imageUrl;
  if (imageUrl && ctx.textureLoader?.loadTexture) {
    ctx.textureLoader.loadTexture(imageUrl).then((loadedTexture) => {
      if (disposed) return;
      imageMaterial.map = loadedTexture;
      imageMaterial.colorNode = texture(loadedTexture);
      imageMaterial.needsUpdate = true;
    }).catch(() => {});
  }

  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  let textOffset = 0.36;

  for (const item of items) {
    if (!item || typeof item.text !== 'string') continue;

    const textObject = ctx.fontAtlas.createText(item.text, {
      fontSize: item.typography?.fontSize ?? 39,
      color: colors.paper,
      align: 'left'
    });

    textObject.position.set(-1.08, textOffset, 0.09);
    root.add(textObject);
    textOffset -= 0.42;
  }

  root.userData.handlers = {};

  root.userData.cleanup = () => {
    if (disposed) return;
    disposed = true;

    for (const timeline of timelines) {
      if (timeline?.kill) timeline.kill();
    }

    for (const material of ownedMaterials) {
      material.dispose?.();
    }

    for (const geometry of ownedGeometries) {
      geometry.dispose?.();
    }

    root.traverse((object) => {
      if (object !== root) object.parent?.remove(object);
    });
  };

  return root;
}
